@Component("procedureOrder-handler")
@ProcessingGroup("procedureOrder-processing-group")
public class ProcedureOrderEventHandler {
	
	// core constructor
	ProcedureOrderEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateProcedureOrderEvent
     */
    @EventHandler
    public void handle( CreateProcedureOrderEvent event) {
        entityManager.persist(new ProcedureOrder(event.getProcedureOrderId(), event.getProcedureCode(), event.getConsentObtained(), event.getOrder(), event.getFacility(), event.getProcedure(), event.getAnesthesiaType()));
    }

    /*
     * @param	event UpdateProcedureOrderEvent
     */
    @EventHandler
    public ProcedureOrder handle( UpdateProcedureOrderEvent event) {
    	entityManager.merge(new ProcedureOrder(event.getProcedureOrderId(), event.getProcedureCode(), event.getConsentObtained(), event.getOrder(), event.getFacility(), event.getProcedure(), event.getAnesthesiaType()));
    }
    
    /*
     * @param	event DeleteProcedureOrderEvent
     */
    @EventHandler
    public void on( DeleteProcedureOrderEvent event) {
    	ProcedureOrder entity = new ProcedureOrder();
   
    	// ------------------------------------------
    	// apply the ProcedureOrderId
    	// ------------------------------------------
    	entity.setProcedureOrderId( event.getProcedureOrderId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final ProcedureOrderRepository procedureOrderEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(ProcedureOrderEventHandler.class.getName());

}
